  "Máxima": { en: "Maximum", de: "Maximal", zh: "最大", ja: "最大", ru: "Максимальное" },
  "Casi sin diferencia visible.": { en: "Almost no visible difference.", de: "Kaum sichtbarer Unterschied.", zh: "几乎看不出差别。", ja: "見た目はほぼ変わりません。", ru: "Почти без видимой разницы." },
  "Ideal para mandar por mail o WhatsApp.": { en: "Great for email or WhatsApp.", de: "Ideal für E-Mail oder WhatsApp.", zh: "适合邮件或微信发送。", ja: "メールやチャットで送るのにぴったり。", ru: "Удобно для почты и мессенджеров." },
  "Lo más chico posible; las fotos pierden algo de detalle.": { en: "As small as possible; photos lose some detail.", de: "So klein wie möglich; Fotos verlieren etwas Detail.", zh: "尽可能小；照片会损失一些细节。", ja: "できるだけ小さく。写真は少し粗くなります。", ru: "Как можно меньше; фото теряют часть деталей." },
  "La contraseña se aplica al guardar. Sin ella, nadie puede abrir el PDF.": { en: "The password is applied when you save. Without it, nobody can open the PDF.", de: "Das Passwort wird beim Speichern gesetzt. Ohne es kann niemand das PDF öffnen.", zh: "密码会在保存时生效。没有密码，任何人都打不开这个 PDF。", ja: "パスワードは保存時に付きます。知らない人は PDF を開けません。", ru: "Пароль применяется при сохранении. Без него PDF никто не откроет." },
  "Contraseña nueva": { en: "New password", de: "Neues Passwort", zh: "新密码", ja: "新しいパスワード", ru: "Новый пароль" },
  "Repetila": { en: "Repeat it", de: "Wiederholen", zh: "再输入一次", ja: "もう一度", ru: "Повторите" },
  "Las contraseñas no coinciden.": { en: "The passwords don't match.", de: "Die Passwörter stimmen nicht überein.", zh: "两次密码不一致。", ja: "パスワードが一致しません。", ru: "Пароли не совпадают." },
  "La contraseña no puede tener comas.": { en: "The password can't contain commas.", de: "Das Passwort darf keine Kommas enthalten.", zh: "密码不能包含逗号。", ja: "パスワードにカンマは使えません。", ru: "В пароле не должно быть запятых." },
  "Usá al menos 4 caracteres.": { en: "Use at least 4 characters.", de: "Mindestens 4 Zeichen verwenden.", zh: "至少 4 个字符。", ja: "4 文字以上にしてね。", ru: "Минимум 4 символа." },
  "Quitar contraseña": { en: "Remove password", de: "Passwort entfernen", zh: "移除密码", ja: "パスワードを外す", ru: "Снять пароль" },
  "Poner contraseña": { en: "Set password", de: "Passwort setzen", zh: "设置密码", ja: "パスワードを付ける", ru: "Установить пароль" },
  "Al guardar, el PDF queda sin contraseña.": { en: "When saved, the PDF will have no password.", de: "Beim Speichern hat das PDF kein Passwort mehr.", zh: "保存后 PDF 将没有密码。", ja: "保存するとパスワードなしになります。", ru: "После сохранения у PDF не будет пароля." },
  "Al guardar, el PDF queda con contraseña.": { en: "When saved, the PDF will be password protected.", de: "Beim Speichern wird das PDF passwortgeschützt.", zh: "保存后 PDF 将受密码保护。", ja: "保存するとパスワード付きになります。", ru: "После сохранения PDF будет защищён паролем." },
