  "Ajustá la app a tu gusto. Se guarda en este equipo.": { en: "Make the app work for you. Saved on this device.", de: "Passe die App an dich an. Wird auf diesem Gerät gespeichert.", zh: "按你的需要调整应用，保存在本设备上。", ja: "使いやすく調整できます。この端末に保存されます。", ru: "Настройте приложение под себя. Сохраняется на этом устройстве." },
  "Tamaño del texto y los botones": { en: "Text and button size", de: "Größe von Text und Schaltflächen", zh: "文字和按钮大小", ja: "文字とボタンの大きさ", ru: "Размер текста и кнопок" },
