  "Colores más fuertes y bordes marcados.": { en: "Stronger colors and clear borders.", de: "Kräftigere Farben und klare Ränder.", zh: "颜色更鲜明，边框更清楚。", ja: "色をはっきり、枠を太く。", ru: "Яркие цвета и чёткие границы." },
  "Menos movimiento": { en: "Reduce motion", de: "Weniger Bewegung", zh: "减少动画", ja: "動きを減らす", ru: "Меньше движения" },
  "Sin animaciones ni saltos.": { en: "No animations or bouncing.", de: "Keine Animationen oder Sprünge.", zh: "没有动画和跳动。", ja: "アニメーションなし。", ru: "Без анимаций и прыжков." },
  "Texto más espaciado": { en: "More text spacing", de: "Mehr Textabstand", zh: "加大文字间距", ja: "文字の間隔を広げる", ru: "Увеличенные интервалы" },
  "Más aire entre letras y renglones.": { en: "More space between letters and lines.", de: "Mehr Platz zwischen Buchstaben und Zeilen.", zh: "字母和行之间更宽松。", ja: "文字と行の間にゆとりを。", ru: "Больше места между буквами и строками." },
  "Labcin lee en voz alta": { en: "Labcin reads aloud", de: "Labcin liest vor", zh: "Labcin 朗读", ja: "Labcin が読み上げる", ru: "Лабсин читает вслух" },
  "Escuchá los tips y avisos.": { en: "Hear the tips and messages.", de: "Hör dir Tipps und Hinweise an.", zh: "听提示和通知。", ja: "コツや案内を音声で。", ru: "Слушайте советы и сообщения." },
  "Listo, te leo los tips en voz alta.": { en: "Okay, I'll read the tips aloud.", de: "Okay, ich lese dir die Tipps vor.", zh: "好的，我会把提示读给你听。", ja: "了解、コツを読み上げるね。", ru: "Хорошо, буду читать советы вслух." },
  "Atajos: Ctrl+O abrir · Ctrl+S guardar · Ctrl+Z deshacer · Supr borrar · Esc cancelar · Alt+A accesibilidad": { en: "Shortcuts: Ctrl+O open · Ctrl+S save · Ctrl+Z undo · Del delete · Esc cancel · Alt+A accessibility", de: "Kürzel: Strg+O öffnen · Strg+S speichern · Strg+Z rückgängig · Entf löschen · Esc abbrechen · Alt+A Barrierefreiheit", zh: "快捷键：Ctrl+O 打开 · Ctrl+S 保存 · Ctrl+Z 撤销 · Delete 删除 · Esc 取消 · Alt+A 无障碍", ja: "ショートカット：Ctrl+O 開く · Ctrl+S 保存 · Ctrl+Z 元に戻す · Delete 削除 · Esc キャンセル · Alt+A アクセシビリティ", ru: "Клавиши: Ctrl+O открыть · Ctrl+S сохранить · Ctrl+Z отменить · Delete удалить · Esc отмена · Alt+A доступность" },
  "Si necesitás letra más grande o más contraste, tocá el botón de accesibilidad o apretá Alt+A.": { en: "If you need bigger text or more contrast, tap the accessibility button or press Alt+A.", de: "Wenn du größere Schrift oder mehr Kontrast brauchst, tippe auf Barrierefreiheit oder drück Alt+A.", zh: "需要更大的字或更高对比度？点无障碍按钮或按 Alt+A。", ja: "文字を大きくしたり、コントラストを上げたいときは、アクセシビリティボタンか Alt+A を押してね。", ru: "Нужен крупный текст или контраст? Нажмите кнопку доступности или Alt+A." },
  "Firmar un documento": { en: "Sign a document", de: "Ein Dokument unterschreiben", zh: "签署文件", ja: "書類に署名", ru: "Подписать документ" },
  "Resaltar y anotar": { en: "Highlight and annotate", de: "Markieren und kommentieren", zh: "高亮和批注", ja: "ハイライトと注釈", ru: "Выделить и подписать" },
  "Escanear con la cámara": { en: "Scan with the camera", de: "Mit der Kamera scannen", zh: "用相机扫描", ja: "カメラでスキャン", ru: "Сканировать камерой" },
  "Unir varios PDF": { en: "Merge several PDFs", de: "Mehrere PDFs zusammenfügen", zh: "合并多个 PDF", ja: "複数の PDF を結合", ru: "Объединить несколько PDF" },
  "Achicar para mandar": { en: "Shrink to send", de: "Zum Versenden verkleinern", zh: "压缩以便发送", ja: "送るために軽く", ru: "Сжать для отправки" },
  "Proteger con contraseña": { en: "Protect with a password", de: "Mit Passwort schützen", zh: "用密码保护", ja: "パスワードで保護", ru: "Защитить паролем" },
  "Tapar datos privados": { en: "Hide private data", de: "Private Daten verbergen", zh: "遮住隐私信息", ja: "個人情報を隠す", ru: "Скрыть личные данные" },
  "Ver todas las herramientas": { en: "See all tools", de: "Alle Werkzeuge ansehen", zh: "查看全部工具", ja: "すべてのツールを見る", ru: "Все инструменты" },
  "¿Qué querés hacer?": { en: "What do you want to do?", de: "Was möchtest du tun?", zh: "你想做什么？", ja: "何をしますか？", ru: "Что хотите сделать?" },
